import itertools

def get_legal_moves(player_moves, all_moves, n):
    legal = []
    for i in range(1, n + 1):
        if i not in all_moves:
            # Rule (ii): cannot choose a number consecutive to any of their own previous choices
            is_consecutive = False
            for move in player_moves:
                if abs(i - move) == 1:
                    is_consecutive = True
                    break
            if not is_consecutive:
                legal.append(i)
    return legal

def solve_game(n):
    # memo for game states
    memo = {}

    def play(alice_moves, bob_moves, turn):
        # Turn 0: Alice, Turn 1: Bob
        state = (tuple(sorted(alice_moves)), tuple(sorted(bob_moves)), turn)
        if state in memo:
            return memo[state]

        all_moves = set(alice_moves) | set(bob_moves)
        if len(all_moves) == n:
            return 0  # Draw

        if turn == 0: # Alice's turn
            legal = get_legal_moves(alice_moves, all_moves, n)
            if not legal:
                return -1 # Bob wins (Alice loses)

            # Alice wants to maximize the result: 1 (win) > 0 (draw) > -1 (loss)
            best_res = -2
            for move in legal:
                res = play(alice_moves | {move}, bob_moves, 1)
                if res > best_res:
                    best_res = res
                if best_res == 1: # Optimization
                    break
            memo[state] = best_res
            return best_res
        else: # Bob's turn
            legal = get_legal_moves(bob_moves, all_moves, n)
            if not legal:
                return 1 # Alice wins (Bob loses)

            # Bob wants to minimize the result: -1 (win) < 0 (draw) < 1 (loss)
            best_res = 2
            for move in legal:
                res = play(alice_moves, bob_moves | {move}, 0)
                if res < best_res:
                    best_res = res
                if best_res == -1: # Optimization
                    break
            memo[state] = best_res
            return best_res

    return play(set(), set(), 0)

for n in range(1, 11):
    print(f"n={n}, result={solve_game(n)}")

