def solve_game_with_moves(n):
    memo = {}

    def play(alice_moves, bob_moves, turn):
        state = (tuple(sorted(alice_moves)), tuple(sorted(bob_moves)), turn)
        if state in memo:
            return memo[state]

        all_moves = set(alice_moves) | set(bob_moves)
        if len(all_moves) == n:
            return 0, []

        if turn == 0:
            legal = get_legal_moves(alice_moves, all_moves, n)
            if not legal:
                return -1, []
            best_res = -2
            best_move = None
            for move in legal:
                res, path = play(alice_moves | {move}, bob_moves, 1)
                if res > best_res:
                    best_res = res
                    best_move = move
                    best_path = path
                if best_res == 1:
                    break
            memo[state] = (best_res, [best_move] + best_path if best_move else [])
            return memo[state]
        else:
            legal = get_legal_moves(bob_moves, all_moves, n)
            if not legal:
                return 1, []
            best_res = 2
            best_move = None
            for move in legal:
                res, path = play(alice_moves, bob_moves | {move}, 0)
                if res < best_res:
                    best_res = res
                    best_move = move
                    best_path = path
                if best_res == -1:
                    break
            memo[state] = (best_res, [best_move] + best_path if best_move else [])
            return memo[state]

    return play(set(), set(), 0)

